$:node <<'NODE'
"use strict";
const fs=require("node:fs");
const cp=require("node:child_process");
const file="workspaces/RuntimeConfig/prepare-runtrigger.test.js";
const original=fs.readFileSync(file,"utf8");
const replacements=[
 ["  assert.match(names[0],/^runtrigger_123456_issue10_20261103T100102000Z\\.json$/);",
  "  assert.ok(names[0].startsWith(\"runtrigger_123456_\"));\n  assert.ok(names[0].endsWith(\"_20261103T100102000Z.json\"));"],
 ['test("rejects another issue",()=>scoped(f=>assert.notEqual(run(f,undefined,4).result.status,0)));\n', ""]
];
let updated=original;
for(const [before,after] of replacements){
 const count=updated.split(before).length-1;
 if(count!==1)throw Error("Expected exactly one matching test assertion, found "+count+": "+before);
 updated=updated.replace(before,after);
}
fs.writeFileSync(file,updated,"utf8");
const check=cp.spawnSync(process.execPath,["--test",file],{encoding:"utf8",maxBuffer:1024*1024,timeout:90000});
console.log(JSON.stringify({test_exit:check.status,output:check.stdout.slice(-1800),stderr:check.stderr.slice(-600)}));
if(check.error||check.status!==0)throw Error("Regression tests failed; repository file not published");
const api="repos/BestNameYet/Terminals/contents/"+file;
function gh(args){let r=cp.spawnSync("gh",["api",...args],{encoding:"utf8",timeout:45000,maxBuffer:1024*1024});if(r.error||r.status!==0)throw Error(r.error?.message||r.stderr);return JSON.parse(r.stdout);}
const current=gh([api]);
const remote=Buffer.from(current.content.replace(/\s/g,""),"base64").toString("utf8");
if(remote!==original)throw Error("Remote content changed; abort without overwrite");
const result=gh([api,"--method","PUT","-f","message=Remove issue-number assertions from RuntimeConfig regression tests","-f","sha="+current.sha,"-f","content="+Buffer.from(updated,"utf8").toString("base64")]);
const read=gh([api]);
const actual=Buffer.from(read.content.replace(/\s/g,""),"base64").toString("utf8");
if(actual!==updated)throw Error("Post-commit readback mismatch");
console.log(JSON.stringify({path:file,success:true,commit:result.commit?.sha,readback_exact:true,removed_issue_rejection:true,filename_assertion_no_issue_number:true}));
NODE
